// between auth.json slots.
const rotation = config.global.codexAccountRotation ?? [];
const authPath = join(homedir(), '.pi/agent/auth.json');
let authSnapshotPath: string | null = null;
if (rotation.length > 0) {
  // Read-only diagnostic. A collision means rotation has fewer unique quota
  // pools than configured, not that auth.json is corrupt. The session layer
  // de-duplicates those slots by accountId before rotating.
  try {
    assertAuthSlotsDistinct(authPath, rotation);
  } catch (err) {
    if (err instanceof AuthSlotCollisionError) {
      log.warn('account.rotation.auth_collision',
        `${err.message} Continuing with duplicate accountIds de-duplicated for rotation.`);
    } else {
      log.warn('account.rotation.auth_check_failed',
        `auth-slot pre-check failed (continuing): ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  authSnapshotPath = snapshotAuthFile(authPath, runId);
  if (authSnapshotPath) {
    log.info('account.rotation.auth_snapshot', `Snapshotted auth.json to ${authSnapshotPath} (read-only on source)`);
  }

  initAccountRotation(rotation);
  log.info('account.rotation.init', `Codex account rotation enabled: ${rotation.join(' → ')}`);
}

